DECLARE prior_dige t bytea; prior_ ync text; prior_job text; prior_outbox text; event_payload j onb;
BEGIN
  IF octet_length(reque t_dige t)<>32 OR length(idempotency_key) NOT BETWEEN 16 AND 128 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid  ync reque t'; END IF;
  PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),$1,$2,$3,$5,$9),0));
  SELECT  .reque t_dige t, .id,j.id,o.id INTO prior_dige t,prior_ ync,prior_job,prior_outbox FROM za p_di covery_ ync   
    JOIN za p_di covery_job  j ON j.organization_id= .organization_id AND j.work pace_id= .work pace_id AND j.environment_id= .environment_id AND j.authority_id= .id AND j.kind='di covery'
