   WHERE  .organization_id=$1 AND  .work pace_id=$2 AND  .environment_id=$3 AND  .integration_id=$5 AND  .idempotency_key=$9;
  IF FOUND THEN IF prior_dige t<>$10 THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='idempotency conflict'; END IF;
    RETURN j onb_build_object(' ync_id',prior_ ync,'job_id',prior_job,'outbox_id',prior_outbox,' tate','queued','replayed',true); END IF;
  IF NOT EXISTS(SELECT 1 FROM za p_integration  i WHERE i.organization_id=$1 AND i.work pace_id=$2 AND i.environment_id=$3 AND i.id=$5 AND i. tate IN ('active','degraded')) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration mi ing'; END IF;
