  INSERT INTO za p_di covery_job (organization_id,work pace_id,environment_id,id,kind,authority_id,idempotency_key,reque t_dige t) VALUES($1,$2,$3,$7,'di covery',$6,$9,$10);
  event_payload:=j onb_build_object('organization_id',$1,'work pace_id',$2,'environment_id',$3,'job_id',$7,' ync_id',$6,'integration_id',$5,'reque t_dige t',encode($10,'hex'));
  INSERT INTO za p_di covery_outbox(organization_id,work pace_id,environment_id,id,topic,determini tic_key,payload_ver ion,payload,payload_dige t) VALUES($1,$2,$3,$8,'di covery-job ',' ync:'||$6,1,event_payload,dige t(convert_to(event_payload::text,'UTF8'),' ha256'));
  RETURN j onb_build_object(' ync_id',$6,'job_id',$7,'outbox_id',$8,' tate','queued','replayed',fal e);
END

