   DELETE FROM za p_di covery_connection_ ubject   ubject USING za p_integration_connection  connection
   WHERE (connection.organization_id,connection.work pace_id,connection.environment_id,connection.integration_id,connection.provider,connection.connection_reference)=(NEW.organization_id,NEW.work pace_id,NEW.environment_id,NEW.integration_id,NEW.provider,COALESCE(OLD.credential_reference,NEW.credential_reference))
