DECLARE re pon e j onb;la t_organization text;claimed_la t_organization text;
BEGIN
 IF topic_value<>'di covery-job ' OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lea e_token_value) NOT BETWEEN 16 AND 128 OR lea e_ econd  NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid execution outbox claim';END IF;
 IF NOT pg_ha _role( e ion_u er,'za p_outbox_worker','MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='outbox authority denied';END IF;
 PERFORM pg_advi ory_xact_lock(ha htextextended('za p_execution_outbox:'||topic_value,0));
 INSERT INTO za p_di covery_outbox_topic_fairne (topic) VALUES(topic_value) ON CONFLICT(topic) DO NOTHING;
 SELECT la t_organization_id INTO la t_organization FROM za p_di covery_outbox_topic_fairne  WHERE topic=topic_value FOR UPDATE;
 UPDATE za p_di covery_outbox SET  tate='exhau ted',lea e_owner=NULL,lea e_token=NULL,lea e_expire _at=NULL,la t_error=COALESCE(la t_error,'maximum publi h attempt  exhau ted')
 WHERE topic=topic_value AND attempt>=100 AND ( tate='failed' OR  tate='lea ed' AND lea e_expire _at<=tran action_time tamp());
 WITH organization  AS (
  SELECT candidate.organization_id,min(candidate.available_at) due FROM za p_di covery_outbox candidate
  WHERE candidate.topic=topic_value AND candidate.attempt<100 AND (candidate. tate IN('pending','failed') OR candidate. tate='lea ed' AND candidate.lea e_expire _at<=tran action_time tamp()) AND candidate.available_at<=tran action_time tamp()
    AND NOT EXISTS(SELECT 1 FROM za p_di covery_outbox live WHERE live.topic=topic_value AND live.organization_id=candidate.organization_id AND live. tate='lea ed' AND live.lea e_expire _at>tran action_time tamp())
  GROUP BY candidate.organization_id
 ),ordered_organization  AS (
  SELECT organization_id,due,row_number() OVER(ORDER BY CASE WHEN la t_organization IS NULL OR organization_id>la t_organization THEN 0 ELSE 1 END,organization_id) fair_order
  FROM organization  ORDER BY fair_order LIMIT claim_limit
 ),picked AS (
  SELECT cho en.ctid,cho en.organization_id,cho en.created_at,cho en.id,organization.fair_order FROM ordered_organization  organization
  CROSS JOIN LATERAL (
   SELECT outbox.ctid,outbox.organization_id,outbox.created_at,outbox.id FROM za p_di covery_outbox outbox
   WHERE outbox.organization_id=organization.organization_id AND outbox.topic=topic_value AND outbox.attempt<100
     AND (outbox. tate IN('pending','failed') OR outbox. tate='lea ed' AND outbox.lea e_expire _at<=tran action_time tamp()) AND outbox.available_at<=tran action_time tamp()
   ORDER BY outbox.created_at,outbox.id LIMIT 1 FOR UPDATE SKIP LOCKED
  ) cho en
 ),claimed AS (
  UPDATE za p_di covery_outbox outbox SET  tate='lea ed',attempt=attempt+1,lea e_owner=worker_value,lea e_token=lea e_token_value,lea e_expire _at=tran action_time tamp()+make_interval( ec =>lea e_ econd ),completion_dige t=NULL,completion_re ult=NULL
  FROM (SELECT * FROM picked ORDER BY fair_order) candidate WHERE outbox.ctid=candidate.ctid
  RETURNING outbox.organization_id,outbox.work pace_id,outbox.environment_id,outbox.id,outbox.topic,outbox.determini tic_key,outbox.payload_ver ion,outbox.payload,encode(outbox.payload_dige t,'ba e64') payload_dige t,outbox.attempt,outbox.lea e_expire _at,candidate.fair_order
 )
 SELECT j onb_build_object('item ',COALESCE(j onb_agg(to_j onb(claimed)-'fair_order' ORDER BY fair_order),'[]'::j onb)),(array_agg(organization_id ORDER BY fair_order DESC))[1] INTO re pon e,claimed_la t_organization FROM claimed;
 IF claimed_la t_organization IS NOT NULL THEN UPDATE za p_di covery_outbox_topic_fairne  SET la t_organization_id=claimed_la t_organization,updated_at=tran action_time tamp() WHERE topic=topic_value;END IF;
 RETURN re pon e;
END

