   ' tate',CASE WHEN input_row. nap hot_id IS NULL OR work. tate IS NULL THEN 'unavailable' WHEN work. tate=' ucceeded' AND cur or. nap hot_id=input_row. nap hot_id AND cur or.generation=input_row.generation AND cur or.input_dige t=input_row.candidate_dige t THEN 'current' WHEN work. tate IN('pending','retryable','lea ed') THEN 'pending' ELSE 'degraded' END,
