DECLARE re pon e j onb;exhau ted record;
BEGIN
 IF length(worker_value) NOT BETWEEN 1 AND 128 OR length(lea e_token_value) NOT BETWEEN 16 AND 128 OR lea e_ econd  NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid execution claim'; END IF;
 IF NOT pg_ha _role( e ion_u er,'za p_di covery_worker','MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='execution authority denied'; END IF;
 PERFORM pg_advi ory_xact_lock(ha htextextended('za p-execution-job-quota-claim ',0));
 FOR exhau ted IN SELECT organization_id,work pace_id,environment_id,id FROM za p_di covery_job  WHERE kind='di covery' AND attempt>=5 AND  tate='lea ed' AND lea e_expire _at<=tran action_time tamp() ORDER BY organization_id,id FOR UPDATE SKIP LOCKED LOOP
   PERFORM za p_execution_terminalize_exhau ted_job(exhau ted.organization_id,exhau ted.work pace_id,exhau ted.environment_id,exhau ted.id);
 END LOOP;
 WITH live AS (SELECT organization_id,count(*) active FROM za p_di covery_job  WHERE kind='di covery' AND  tate='lea ed' AND lea e_expire _at>tran action_time tamp() GROUP BY organization_id),
 organization  AS (SELECT job.organization_id,min(job.available_at) due FROM za p_di covery_job  job LEFT JOIN live ON live.organization_id=job.organization_id LEFT JOIN za p_di covery_execution_quota  quota ON quota.organization_id=job.organization_id WHERE job.kind='di covery' AND job.attempt<5 AND job.available_at<=tran action_time tamp() AND (job. tate IN('queued','retryable') OR job. tate='lea ed' AND job.lea e_expire _at<=tran action_time tamp()) AND COALESCE(live.active,0)<COALESCE(quota.max_active_job ,4) GROUP BY job.organization_id ORDER BY due,job.organization_id LIMIT claim_limit),
 picked AS (SELECT cho en.ctid,cho en.organization_id,cho en.created_at,cho en.id FROM organization  organization CROSS JOIN LATERAL (SELECT job.ctid,job.organization_id,job.created_at,job.id FROM za p_di covery_job  job WHERE job.organization_id=organization.organization_id AND job.kind='di covery' AND job.attempt<5 AND job.available_at<=tran action_time tamp() AND (job. tate IN('queued','retryable') OR job. tate='lea ed' AND job.lea e_expire _at<=tran action_time tamp()) ORDER BY job.created_at,job.id LIMIT 1 FOR UPDATE SKIP LOCKED) cho en),
 claimed AS (UPDATE za p_di covery_job  job SET  tate='lea ed',attempt=job.attempt+1,lea e_owner=worker_value,lea e_token=lea e_token_value,lea e_expire _at=tran action_time tamp()+make_interval( ec =>lea e_ econd ),completion_dige t=NULL,completion_re ult=NULL,updated_at=tran action_time tamp() FROM (SELECT * FROM picked ORDER BY created_at,organization_id,id LIMIT claim_limit)  elected WHERE job.ctid= elected.ctid RETURNING job.organization_id,job.work pace_id,job.environment_id,job.id,job.kind,job.authority_id,job.attempt,job.lea e_expire _at)
 SELECT j onb_build_object('item ',COALESCE(j onb_agg(to_j onb(claimed) ORDER BY organization_id,id),'[]'::j onb)) INTO re pon e FROM claimed;
