  RETURN j onb_build_object('integration_id',integration_value,'connection_id',connection_value,'provider',provider_value,' ubject_kind',kind_value,' ubject_id',id_value,'connection_ver ion',expected_connection_ver ion,'verified_at', ubject_row.verified_at);
