DECLARE re pon e j onb;required_role text; BEGIN
 IF length(worker) NOT BETWEEN 1 AND 128 OR length(lea e_token) NOT BETWEEN 16 AND 128 OR lea e_ econd  NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 100 OR reque ted_kind NOT IN('di covery','runtime','projection') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid job claim'; END IF;
 required_role:=CASE WHEN reque ted_kind='runtime' THEN 'za p_runtime_worker' ELSE 'za p_di covery_worker' END;
 IF NOT pg_ha _role( e ion_u er,required_role,'MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='job authority denied';END IF;
 WITH exhau ted AS (UPDATE za p_di covery_job  SET  tate='failed',la t_error=COALESCE(la t_error,'lea e expired after maximum attempt '),completed_at=tran action_time tamp(),lea e_owner=NULL,lea e_token=NULL,lea e_expire _at=NULL,updated_at=tran action_time tamp() WHERE kind=reque ted_kind AND attempt>=5 AND  tate='lea ed' AND lea e_expire _at<=tran action_time tamp() RETURNING organization_id,work pace_id,environment_id,kind,authority_id,la t_error,attempt)
 UPDATE za p_di covery_ ync    SET  tate='failed',attempt=e.attempt,la t_error=e.la t_error,completed_at=tran action_time tamp() FROM exhau ted e WHERE e.kind='di covery' AND  .organization_id=e.organization_id AND  .work pace_id=e.work pace_id AND  .environment_id=e.environment_id AND  .id=e.authority_id AND  . tate IN('queued','running');
 WITH organization  AS (SELECT organization_id,min(available_at) due FROM za p_di covery_job  WHERE kind=reque ted_kind AND attempt<5 AND ( tate IN('queued','retryable') OR  tate='lea ed' AND lea e_expire _at<=tran action_time tamp()) AND available_at<=tran action_time tamp() GROUP BY organization_id ORDER BY due,organization_id LIMIT claim_limit),
 picked AS (SELECT cho en.ctid,cho en.organization_id,cho en.created_at,cho en.id FROM organization  g CROSS JOIN LATERAL (SELECT j.ctid,j.organization_id,j.created_at,j.id FROM za p_di covery_job  j WHERE j.organization_id=g.organization_id AND j.kind=reque ted_kind AND j.attempt<5 AND (j. tate IN('queued','retryable') OR j. tate='lea ed' AND j.lea e_expire _at<=tran action_time tamp()) AND j.available_at<=tran action_time tamp() ORDER BY j.created_at,j.id LIMIT 1 FOR UPDATE SKIP LOCKED) cho en),
 claimed AS (UPDATE za p_di covery_job  j SET  tate='lea ed',attempt=attempt+1,lea e_owner=worker,lea e_token=$2,lea e_expire _at=tran action_time tamp()+make_interval( ec =>$3),completion_dige t=NULL,completion_re ult=NULL,updated_at=tran action_time tamp() FROM (SELECT * FROM picked ORDER BY created_at,organization_id,id LIMIT claim_limit) p WHERE j.ctid=p.ctid RETURNING j.organization_id,j.work pace_id,j.environment_id,j.id,j.kind,j.authority_id,j.attempt,j.lea e_expire _at)
 SELECT j onb_build_object('item ',COALESCE(j onb_agg(to_j onb(claimed) ORDER BY organization_id,id),'[]'::j onb)) INTO re pon e FROM claimed;
 UPDATE za p_di covery_ ync    SET  tate='running',attempt=j.attempt, tarted_at=COALESCE( . tarted_at,tran action_time tamp()),la t_error=NULL FROM za p_di covery_job  j WHERE j.kind='di covery' AND j.lea e_owner=worker AND j.lea e_token=$2 AND  .organization_id=j.organization_id AND  .work pace_id=j.work pace_id AND  .environment_id=j.environment_id AND  .id=j.authority_id AND  . tate IN('queued','running');
