 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;run_row zasp_discovery_schedule_runs%ROWTYPE;schedule_row zasp_discovery_schedules%ROWTYPE;digest_value bytea;
BEGIN
