  AND (c.evidence_reference,c.evidence_key,c.evidence_version_id,c.evidence_checksum,c.evidence_size)=(t.evidence_reference,t.evidence_key,t.evidence_version_id,t.evidence_checksum,t.evidence_size) THEN
