CREATE OR REPLACE FUNCTION zasp_sa_webhook_prior.definition_activate_core(organization_value text, workspace_value text, environment_value text, definition_value text, actor_value text, idempotency_value text, expected_version bigint, target_activation text, fresh_auth_expires_value timestamp with time zone, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE binding_value jsonb; definition_row zasp_security_agent_definitions%ROWTYPE; receipt_row zasp_security_agent_request_receipts%ROWTYPE; action_value text; intent_value jsonb; response_value jsonb; intent_digest_value bytea;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR target_activation NOT IN('validated','supervised','autonomous') OR length(actor_value) NOT BETWEEN 1 AND 128 OR length(audit_value) NOT BETWEEN 1 AND 128 OR length(correlation_value) NOT BETWEEN 1 AND 128 OR length(receipt_value) NOT BETWEEN 1 AND 128
     OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR fresh_auth_expires_value IS NULL OR fresh_auth_expires_value<=clock_timestamp() OR fresh_auth_expires_value>transaction_timestamp()+interval '5 minutes 5 seconds' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent activation rejected';
  END IF;
  intent_value:=jsonb_build_object('activation',target_activation,'expected_version',expected_version,'resource_id',definition_value);
  intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt
  WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=clock_timestamp()
       OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions current_definition WHERE (current_definition.organization_id,current_definition.workspace_id,current_definition.environment_id,current_definition.definition_id)=(organization_value,workspace_value,environment_value,definition_value) AND current_definition.deleted_at IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent activation replay conflict';
    END IF;

    IF fresh_auth_expires_value<=clock_timestamp() OR receipt_row.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent activation authority expired';END IF;
    IF target_activation IN('supervised','autonomous') AND EXISTS(SELECT 1 FROM public.zasp_security_agent_definition_versions h
      WHERE (h.organization_id,h.workspace_id,h.environment_id,h.definition_id,h.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version)
       AND (h.definition ? 'existing_test' OR h.definition->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab'])) THEN
     SELECT * INTO definition_row FROM public.zasp_security_agent_definitions
      WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(organization_value,workspace_value,environment_value,definition_value,(receipt_row.response->>'version')::bigint) AND deleted_at IS NULL FOR SHARE;
     IF NOT FOUND OR definition_row.activation IS DISTINCT FROM target_activation OR definition_row.body->>'autonomy' IS DISTINCT FROM target_activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test activation replay changed';END IF;
